// Package activityrelations holds the Go relation plans generated from the Activity bindings and
// their Go registrations, so the probe and explore harnesses can correlate actual invocations and
// project their responses to novelty keys in process. The plans, descriptor subset and
// differential vectors are regenerated by the Rust control relation_plans (UMPIRE_BLESS=1).
package activityrelations

import (
	_ "embed"
	"fmt"
	"strings"

	"github.com/temporalio/umpire/hosts/go/relation"
	"google.golang.org/protobuf/reflect/protoreflect"
)

// descriptorSet is the exact admitted descriptor subset the plans were generated against.
//
//go:embed relation-api.binpb
var descriptorSet []byte

// Plans are the generated relation plans, one per bound RPC.
func Plans() []*relation.RPCRelationPlan {
	return []*relation.RPCRelationPlan{&StartPlan, &DescribePlan, &CancelPlan}
}

// Receipt is the admitted ProposalContext receipt: the run established by the Start that
// created the Activity.
func Receipt(runID string) relation.ReceiptSlots {
	return relation.ReceiptSlots{"run_id": relation.Present(protoreflect.ValueOfString(runID))}
}

// registry returns the Go registrations of a plan's named Rust adapters. None of the current
// run-identity declarations names one; a plan that does is refused until it is registered here.
func registry(*relation.RPCRelationPlan) *relation.Registry {
	return relation.NewRegistry()
}

// Bindings checks and projects invocations of every bound RPC, keyed by full method name.
type Bindings map[string]*relation.Novelty

// NewBindings admits every plan against the embedded descriptor subset.
func NewBindings() (Bindings, error) {
	bindings := Bindings{}
	for _, plan := range Plans() {
		novelty, err := relation.NewNovelty(plan, registry(plan), descriptorSet)
		if err != nil {
			return nil, fmt.Errorf("%s: %w", plan.Method, err)
		}
		bindings[plan.Method] = novelty
	}
	return bindings, nil
}

// For returns the binding of a gRPC method name, with or without its leading slash.
func (b Bindings) For(method string) (*relation.Novelty, bool) {
	novelty, ok := b[strings.TrimPrefix(method, "/")]
	return novelty, ok
}
